def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_def = sum(1 for _, o in history if o == 'D')
    if opp_def <= 1 and last_opp == 'C':
        return 'C'

    opp_c = n - opp_def
    if opp_c <= 2 and n >= 8:
        return 'D'

    same_count = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same_count += 1
        else:
            break

    if last_opp == 'D' and same_count >= 4:
        if rng.randint(0, 3) == 0:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        return 'C'
    else:
        if last_me == 'D':
            return 'D'
        if n >= 2:
            prev_me, prev_opp = history[-2]
            if prev_me == 'D' and prev_opp == 'C':
                return 'C'
        return 'D'
